const cfg = $('Config').first().json;
const clean = s => String(s || '').replace(/\s+/g, ' ').trim();
const emails = $input.all().map(i => i.json).filter(e => e && e.id);
const list = emails.slice(0, Number(cfg.maxEmails) || 50).map((e, i) => ({
  n: i + 1,
  id: e.id,
  de: clean(e.From),
  assunto: clean(e.Subject),
  snippet: clean(e.snippet).slice(0, 300)
}));
const agora = $now.setZone('America/Fortaleza').toFormat("yyyy-MM-dd HH:mm (cccc)");

const system = `Você é um assistente executivo que triá e-mails. Responda SOMENTE com um JSON válido, sem markdown e sem texto fora do JSON.

Formato:
{
  "resumo": "2 a 3 frases com o panorama do dia",
  "emails": [
    {
      "n": 1,
      "topico": "Financeiro/Cobrança | Clientes | Trabalho | Pessoal | Notificações/Newsletters | Outros",
      "urgencia": "alta | media | baixa",
      "motivo": "por que essa urgência (curto)",
      "acao": "próxima ação objetiva, no imperativo (curto)",
      "prazo": "YYYY-MM-DD ou null",
      "precisa_agendar": true
    }
  ]
}

Regras:
- Inclua TODOS os e-mails recebidos, usando o mesmo "n".
- urgencia "alta": prazo em até 48h, cobrança/pagamento pendente, cliente ou chefia aguardando, problema em andamento.
- urgencia "media": exige resposta ou ação, mas sem prazo curto.
- urgencia "baixa": informativo, newsletter, promoção, notificação automática.
- precisa_agendar = true só quando há ação concreta a fazer (urgência alta ou media). Newsletters e promoções sempre false.
- "prazo" só se estiver explícito ou claramente inferível no e-mail; caso contrário null.
- Escreva em português do Brasil.`;

const userPrompt = `Data e hora atuais: ${agora}\n\nE-mails das últimas 24h (JSON):\n${JSON.stringify(list)}`;

return [{ json: { list, count: list.length, system, userPrompt } }];

const raw = $json.message?.content ?? $json.content?.find(c => c.type === 'text')?.text ?? '';
let data = null;
try { data = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { data = JSON.parse(m[0]); } catch (e2) {} }
}
if (!data || !Array.isArray(data.emails)) {
  throw new Error('A IA não devolveu JSON válido: ' + raw.slice(0, 300));
}

const list = $('Prepare').first().json.list;
const zone = 'America/Fortaleza';
const hoje = DateTime.now().setZone(zone).startOf('day');
const ordem = { alta: 0, media: 1, baixa: 2 };
const emoji = { alta: '🔴', media: '🟡', baixa: '🟢' };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const itens = data.emails.map(x => {
  const o = list.find(l => l.n === x.n) || {};
  const urg = ordem[x.urgencia] !== undefined ? x.urgencia : 'baixa';
  return { ...x, urgencia: urg, de: o.de || '', assunto: o.assunto || '' };
}).sort((a, b) => ordem[a.urgencia] - ordem[b.urgencia]);

const events = itens.filter(x => x.precisa_agendar === true).map(x => {
  let dia = hoje;
  let hora = x.urgencia === 'alta' ? 11 : 16;
  if (/^\d{4}-\d{2}-\d{2}$/.test(x.prazo || '')) {
    const d = DateTime.fromISO(x.prazo, { zone });
    if (d.isValid && d >= hoje) { dia = d; hora = 9; }
  }
  const start = dia.set({ hour: hora, minute: 0, second: 0, millisecond: 0 });
  return {
    start: start.toISO(),
    end: start.plus({ minutes: 30 }).toISO(),
    summary: `${emoji[x.urgencia]} ${x.acao || x.assunto}`.slice(0, 120),
    description: `De: ${x.de}\nAssunto: ${x.assunto}\nMotivo: ${x.motivo || ''}\nPrazo: ${x.prazo || '—'}\nTópico: ${x.topico || ''}`
  };
});

const cont = { alta: 0, media: 0, baixa: 0 };
itens.forEach(i => cont[i.urgencia]++);
const topicos = {};
itens.forEach(i => { (topicos[i.topico || 'Outros'] ||= []).push(i); });

let html = `<h2>📬 Resumo dos e-mails — ${hoje.toFormat('dd/MM/yyyy')}</h2>`
  + `<p>${esc(data.resumo || '')}</p>`
  + `<p><b>${itens.length}</b> e-mails: 🔴 ${cont.alta} · 🟡 ${cont.media} · 🟢 ${cont.baixa} · 📅 ${events.length} na agenda</p>`;
for (const [t, arr] of Object.entries(topicos)) {
  html += `<h3>${esc(t)} (${arr.length})</h3><ul>` + arr.map(i =>
    `<li>${emoji[i.urgencia]} <b>${esc(i.assunto)}</b> — ${esc(i.de)}<br>${esc(i.acao || i.motivo || '')}`
    + `${/^\d{4}-/.test(i.prazo || '') ? ' <i>(prazo ' + esc(i.prazo) + ')</i>' : ''}</li>`
  ).join('') + '</ul>';
}

return [{ json: { events, summaryHtml: html, subject: `📬 Resumo de e-mails — ${hoje.toFormat('dd/MM')} (🔴 ${cont.alta} urgentes)` } }];
